INSERT INTO public.mail_message VALUES (359, NULL, 10817, NULL, NULL, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'notification', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<848193899677718.1767165319.788071632385254-openerp-message-notify@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '', NULL, true, NULL, false, '2025-12-31 07:15:19', NULL, '2025-12-31 07:15:19.744341', '2025-12-31 07:15:19.744341');
INSERT INTO public.mail_message VALUES (360, NULL, 2067, NULL, 1, 20, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'notification', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<663154036838350.1767166735.468164443969727-openerp-2067-crm.lead@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '', NULL, NULL, NULL, true, '2025-12-31 07:38:55', NULL, '2025-12-31 07:38:55.424024', '2025-12-31 07:38:55.424024');
INSERT INTO public.mail_message VALUES (361, 360, 2067, NULL, 1, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'comment', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<555884471606499.1767166911.506773471832275-openerp-2067-crm.lead@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '<span>Spoke to miss manah, she said Hi. We already have a CRM, right now we''re looking for tools for messages or email campaign. Do you have anything? Offered available service from ERP solution and she said she will try to set the appointment secured with the decision maker. Now she gave the number of the manager Miss Dalila contact number +971 55 578 3400 however she claim not to be the right person to decide about this. Asked her about the contact number of the right person but she said just to call the main office number and disconnected the call. Now called back to Miss Manah and informed her what Dalila said, miss mana said she will forward to the marketing team instead.</span>', NULL, NULL, NULL, true, '2025-12-31 07:41:51', NULL, '2025-12-31 07:41:51.492252', '2025-12-31 07:41:51.492252');
INSERT INTO public.mail_message VALUES (368, 367, 3623, NULL, 1, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'comment', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<566892036443183.1767170400.151561021804810-openerp-3623-crm.lead@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '<span>Spoke to admin and informed about the ERP solution however she said that she can only provide an email address where we could send our proposal and company profile then it will be forwarded to the marketing team, asked her about the decision maker. She said she is not allowed to provide an information of that person. Asked her a WhatsApp number to send the company profile. She provided.</span>', NULL, NULL, NULL, true, '2025-12-31 08:40:00', NULL, '2025-12-31 08:40:00.13706', '2025-12-31 08:40:00.13706');
INSERT INTO public.mail_message VALUES (369, NULL, 3623, NULL, NULL, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'notification', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<712052724464005.1767170433.345426321029663-openerp-message-notify@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '', NULL, true, NULL, false, '2025-12-31 08:40:33', NULL, '2025-12-31 08:40:33.304206', '2025-12-31 08:40:33.304206');
INSERT INTO public.mail_message VALUES (370, NULL, 4951, NULL, 1, 20, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'notification', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<682668887629553.1767170475.664515018463135-openerp-4951-crm.lead@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '', NULL, NULL, NULL, true, '2025-12-31 08:41:15', NULL, '2025-12-31 08:41:15.611294', '2025-12-31 08:41:15.611294');
INSERT INTO public.mail_message VALUES (371, NULL, 4951, NULL, NULL, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'notification', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<994164506221546.1767170514.693863630294800-openerp-message-notify@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '', NULL, true, NULL, false, '2025-12-31 08:41:54', NULL, '2025-12-31 08:41:54.641075', '2025-12-31 08:41:54.641075');
INSERT INTO public.mail_message VALUES (372, NULL, 4951, NULL, NULL, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'notification', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<880628820846349.1767170523.437050580978394-openerp-message-notify@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '', NULL, true, NULL, false, '2025-12-31 08:42:03', NULL, '2025-12-31 08:42:03.383241', '2025-12-31 08:42:03.383241');
INSERT INTO public.mail_message VALUES (373, 372, 4951, NULL, 1, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'comment', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<306990775726932.1767170598.552220344543457-openerp-4951-crm.lead@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '<span>Spoke to Mr. Sheik, the accounting in charge and informed him about the ERP solution, he said he will try to get the appointment with the management however it is not their focus as of now. They don''t have requirements, tried to overcome the challenge and he provided his WhatsApp number and said to call back in 2 days, and send the company profile on WhatsApp first.</span>', NULL, NULL, NULL, true, '2025-12-31 08:43:18', NULL, '2025-12-31 08:43:18.523658', '2025-12-31 08:43:18.523658');
