INSERT INTO public.mail_message VALUES (407, 406, 8664, NULL, 1, 20, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'notification', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<360685619438821.1767331574.488870382308960-openerp-8664-crm.lead@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '', NULL, NULL, NULL, true, '2026-01-02 05:26:14', NULL, '2026-01-02 05:26:14.448603', '2026-01-02 05:26:14.448603');
INSERT INTO public.mail_message VALUES (408, 407, 8664, NULL, 1, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'comment', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, NULL, '<891070304309570.1767331879.144477367401123-openerp-8664-crm.lead@1bf84fc548eb>', '"MIchael GUido" <m.guido@scholarixglobal.com>', NULL, '<span>Mr. Dilmurod said he will talk to his IT first after our conference about the ERP solution. The reason behind it is because he wants to know if this system can be integrated to his plan for his company. He said that he doesn''t need the service however he also said that give him 3 months, until March and he will figure out if he really needs the service. He lost his sales agents, they left to a different company. He shut down his website after the agents left. He wants to find out how he can make his first company sales happen. We''ve been in touch with him.</span>', NULL, NULL, NULL, true, '2026-01-02 05:31:19', NULL, '2026-01-02 05:31:19.113753', '2026-01-02 05:31:19.113753');
