INSERT INTO public.mail_message VALUES (519, 518, 2782, NULL, 1, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'comment', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, NULL, '<715540256257466.1767345196.024747610092163-openerp-2782-crm.lead@1bf84fc548eb>', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, '<span>Spoke to Miss Justine about the ERP solution, she said that the company is not looking to having a system for the business as of now, they only use property finder and dubizzel and excel. Now informed her the referral promotion in our company for those who could arrange a possible opportunity for us to present to the owners or decision makers, she provided the mobile number of the CEO and said 10 employees their company has. No ERP or CRM at all.<br><br>[12:55 pm, 02/01/2026] Justine - Diamond City Real Estate: Sadaf Javaid<br>[12:56 pm, 02/01/2026] Justine - Diamond City Real Estate: +971 50 217 6037</span>', NULL, NULL, NULL, true, '2026-01-02 09:13:16', NULL, '2026-01-02 09:13:16.004811', '2026-01-02 09:13:16.004811');
