INSERT INTO public.mail_message VALUES (546, NULL, 10922, NULL, NULL, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'notification', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, NULL, '<424849192611086.1767353114.344902992248535-openerp-message-notify@1bf84fc548eb>', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, '', NULL, true, NULL, false, '2026-01-02 11:25:14', NULL, '2026-01-02 11:25:14.311591', '2026-01-02 11:25:14.311591');
INSERT INTO public.mail_message VALUES (547, 546, 10922, NULL, 1, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'comment', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, NULL, '<771562184855488.1767353134.103767156600952-openerp-10922-crm.lead@1bf84fc548eb>', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, '<span>Spoke to Miss Joy today about the ERP solution, the last time we spoke she introduced me to Mr. Makul, and throughout our conversation, Mr. Makul mentioned that he will talk to the boss, Mr. Ali about this opportunity and he will get back to me with him asking my contact number. Now today he said that he managed to discuss about it however they are waiting for the "Go Signal" from the decision maker as per him, and he said he will let us know the moment they receive it. We will discuss again by Monday as per him.</span>', NULL, NULL, NULL, true, '2026-01-02 11:25:34', NULL, '2026-01-02 11:25:34.091466', '2026-01-02 11:25:34.091466');
INSERT INTO public.mail_message VALUES (548, NULL, 10922, NULL, NULL, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'notification', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, NULL, '<842612614105961.1767353262.998317003250122-openerp-message-notify@1bf84fc548eb>', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, '', NULL, true, NULL, false, '2026-01-02 11:27:42', NULL, '2026-01-02 11:27:42.962169', '2026-01-02 11:27:42.962169');
INSERT INTO public.mail_message VALUES (549, 547, 10922, NULL, 1, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'comment', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, NULL, '<627100488802993.1767353642.810309886932373-openerp-10922-crm.lead@1bf84fc548eb>', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, '<span>Called and spoke to Joy today, Mr. Makul is sometime available in the office when it is friday, now she tried to transfer the call and Mr. Makul is not available however another person answered, name is Maguli the call, and he took our contact details in order to provide it to Mr. Makul on Monday.</span>', NULL, NULL, NULL, true, '2026-01-02 11:34:02', NULL, '2026-01-02 11:34:02.787361', '2026-01-02 11:34:02.787361');
INSERT INTO public.mail_message VALUES (550, 489, 10817, NULL, 1, 2, NULL, 6, NULL, NULL, 5, 5, NULL, 'crm.lead', 'comment', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, NULL, '<507202661158752.1767354116.643880128860474-openerp-10817-crm.lead@1bf84fc548eb>', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, '<span>Informed Mr. Binya about the conference this Monday however he didn''t respond yet.</span>', NULL, NULL, NULL, true, '2026-01-02 11:41:56', NULL, '2026-01-02 11:41:56.630338', '2026-01-02 11:41:56.630338');
