INSERT INTO public.mail_message VALUES (591, NULL, 1, 1, 1, 2, NULL, 6, NULL, NULL, 5, 1, 'Invitation to DIAMOND CITY REAL ESTATE BROKER', 'calendar.event', 'user_notification', '"MIchael Guido" <m.guido@scholarixglobal.com>', NULL, NULL, '<191606800075466.1767361010.645015954971313-openerp-message-notify@1bf84fc548eb>', '"MIchael Guido" <catchall@sgctech.ai>', 'mail.mail_notification_light', '<div style="font-size:13px; color:#374151">

    <h1 style="font-size:18px; font-weight:bold; color:#374151; margin-bottom:28px">
        Invitation
    </h1>
    <p style="margin:0">
        <span style="display:block; margin-bottom:8px">Hello Saifulla,</span>

                MIchael Guido invited you for the <strong>DIAMOND CITY REAL ESTATE BROKER</strong> meeting.

    </p>
    <div style="text-align:center; padding:16px 0px 16px 0px">
        <a href="http://odoo.scholarixglobal.com/calendar/meeting/accept?token=93bfaf576a2e47a6a4febd3328fac031&amp;id=1" style="display:inline-block; padding:7px 14px; color:#FFFFFF; text-decoration:none; background-color:#875A7B; border-radius:3px">
            Accept</a>
        <a href="http://odoo.scholarixglobal.com/calendar/meeting/decline?token=93bfaf576a2e47a6a4febd3328fac031&amp;id=1" style="display:inline-block; margin-left:6px; padding:7px 14px; color:#FFFFFF; text-decoration:none; background-color:#875A7B; border-radius:3px">
            Decline</a>
        <a href="http://odoo.scholarixglobal.com/calendar/meeting/view?token=93bfaf576a2e47a6a4febd3328fac031&amp;id=1" style="display:inline-block; margin-left:12px; padding:7px 14px; color:#111827; text-decoration:none; background-color:#E7E9ED; border-radius:3px">
            View</a>
    </div>
    <div style="margin:16px 0 0">
        <h2 style="margin-bottom:12px; font-size:14px; font-weight:bold; color:#875A7B">Details</h2>
        <table cellpadding="0" cellspacing="0" border="0" style="font-size:13px; color:#374151">
            <tr>
                <td style="width:100px; color:#676F7B">Date &amp; Time</td>
                <td style="font-weight:bold">
                    Monday
                    5
                    January 2026
                        1:00 PM
                            <span style="font-size:11px; font-weight:normal">
                                (Asia/Dubai)
                            </span>
                </td>
            </tr>
            <tr>
                <td style="width:100px; padding-top:6px; color:#676F7B">Duration</td>
                <td style="padding-top:6px">1H00</td>
            </tr>
            <tr>
                <td style="width:100px; padding-top:6px; color:#676F7B; vertical-align:top">Location</td>
                <td style="padding-top:6px">
                    Office 1801, Sidra Tower, Al Sufouh 1, Sheikh Zayed Rd, Dubai, United Arab Emirates.
                    <a target="_blank" style="margin-left:12px; font-size:12px; color:#008f8c; text-decoration:underline" href="http://maps.google.com/maps?oi=map&amp;q=Office%201801,%20Sidra%20Tower,%20Al%20Sufouh%201,%20Sheikh%20Zayed%20Rd,%20Dubai,%20United%20Arab%20Emirates.">View Map</a>
                </td>
            </tr>
        </table>
    </div>
    <div style="margin:32px 0 0">
        <h2 style="margin-bottom:12px; font-size:14px; font-weight:bold; color:#875A7B">Attendees</h2>
        <div style="margin-bottom:5px">
            <img style="border:0; width:15px; height:15px; vertical-align:text-bottom" src="http://odoo.scholarixglobal.com/calendar/static/src/img/state_accepted.png">
                <span style="margin-left:5px">MIchael Guido</span>
        </div><div style="margin-bottom:5px">
            <img style="border:0; width:15px; height:15px; vertical-align:text-bottom" src="http://odoo.scholarixglobal.com/calendar/static/src/img/state_needsAction.png">
                <span style="margin-left:5px">Renbran Madelo</span>
        </div><div style="margin-bottom:5px">
            <img style="border:0; width:15px; height:15px; vertical-align:text-bottom" src="http://odoo.scholarixglobal.com/calendar/static/src/img/state_needsAction.png">
                <span style="margin-left:5px">Administrator</span>
        </div><div style="margin-bottom:5px">
            <img style="border:0; width:15px; height:15px; vertical-align:text-bottom" src="http://odoo.scholarixglobal.com/calendar/static/src/img/state_needsAction.png">
                <span style="margin-left:5px">You</span>
        </div>
    </div>
    <div style="margin:32px 0 0">
        <h2 style="margin-bottom:12px; font-size:14px; font-weight:bold; color:#875A7B">Description of the event</h2>
        <div><strong>Organized by</strong><br>MIchael Guido<br><a href="mailto:m.guido@scholarixglobal.com">m.guido@scholarixglobal.com</a><br><br><strong>Contact Details</strong><br>Administrator<br><a href="mailto:info@sgctech.ai">info@sgctech.ai</a><br><a href="tel:+971%2056%20390%205772">+971 56 390 5772</a></div>
    </div>
    <p style="margin:32px 0 0">
        Thank you!
            <span style="display:block; margin-top:8px"><div>MIchael GUido</div></span>
    </p>
</div>
