    <div style="text-align:center; padding:16px 0px 16px 0px">
        <a href="http://odoo.scholarixglobal.com/calendar/meeting/accept?token=dcb8c85b500d4618a0a1ec7fb304c74f&amp;id=1" style="display:inline-block; padding:7px 14px; color:#FFFFFF; text-decoration:none; background-color:#875A7B; border-radius:3px">
            Accept</a>
