            Decline</a>
        <a href="http://odoo.scholarixglobal.com/calendar/meeting/view?token=dcb8c85b500d4618a0a1ec7fb304c74f&amp;id=1" style="display:inline-block; margin-left:12px; padding:7px 14px; color:#111827; text-decoration:none; background-color:#E7E9ED; border-radius:3px">
            View</a>
    </div>
    <div style="margin:16px 0 0">
        <h2 style="margin-bottom:12px; font-size:14px; font-weight:bold; color:#875A7B">Details</h2>
        <table cellpadding="0" cellspacing="0" border="0" style="font-size:13px; color:#374151">
            <tr>
                <td style="width:100px; color:#676F7B">Date &amp; Time</td>
                <td style="font-weight:bold">
                    Monday
                    5
                    January 2026
                        1:00 PM
                            <span style="font-size:11px; font-weight:normal">
                                (Asia/Dubai)
                            </span>
                </td>
            </tr>
            <tr>
                <td style="width:100px; padding-top:6px; color:#676F7B">Duration</td>
                <td style="padding-top:6px">1H00</td>
            </tr>
            <tr>
                <td style="width:100px; padding-top:6px; color:#676F7B; vertical-align:top">Location</td>
                <td style="padding-top:6px">
                    Office 1801, Sidra Tower, Al Sufouh 1, Sheikh Zayed Rd, Dubai, United Arab Emirates.
                    <a target="_blank" style="margin-left:12px; font-size:12px; color:#008f8c; text-decoration:underline" href="http://maps.google.com/maps?oi=map&amp;q=Office%201801,%20Sidra%20Tower,%20Al%20Sufouh%201,%20Sheikh%20Zayed%20Rd,%20Dubai,%20United%20Arab%20Emirates.">View Map</a>
                </td>
            </tr>
        </table>
    </div>
    <div style="margin:32px 0 0">
        <h2 style="margin-bottom:12px; font-size:14px; font-weight:bold; color:#875A7B">Attendees</h2>
        <div style="margin-bottom:5px">
            <img style="border:0; width:15px; height:15px; vertical-align:text-bottom" src="http://odoo.scholarixglobal.com/calendar/static/src/img/state_accepted.png">
                <span style="margin-left:5px">MIchael Guido</span>
        </div><div style="margin-bottom:5px">
